import React, { useEffect } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Button,
  Card,
  CardContent,
  CardMedia,
  Chip,
  Divider,
  Grid,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  AccountBalance as FinanceIcon,
  ArrowForward as ArrowForwardIcon,
  AutoGraph as IntelligenceIcon,
  ExpandMore as ExpandMoreIcon,
  GppGood as PatentIcon,
  Info as AboutIcon,
  Insights as InsightsIcon,
  Login as LoginIcon,
  PersonAdd as RegisterIcon,
  MailOutline as ContactIcon,
  Nature as EcoIcon,
  Factory as FactoryIcon,
  Public as ClimateIcon,
  Savings as SavingsIcon,
  Speed as TransitionIcon,
  TrackChanges as MeasureIcon,
  Forest as OffsetsIcon,
  CurrencyRupee as PricingIcon,
} from '@mui/icons-material';
import { Link as RouterLink, useLocation, useNavigate } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import { useRegistration } from '../context/RegistrationContext';
import BrandLockup from './BrandLockup';
import { BRAND_BODY_LOGO_SRC } from '../constants/brand';
import { usePublicPricingVisibility } from '../hooks/usePublicPricingVisibility';
import {
  ABOUT_US_SECTION,
  CARBON_OFFSET_TEASER_SECTION,
  CLIMATE_AND_SAVINGS_HIGHLIGHTS,
  INDIA_SPECIFIC_INFO,
  PATENT_PENDING_HIGHLIGHT,
  PLATFORM_BENEFITS,
  POST_LOGIN_WORKFLOW,
  PRE_LOGIN_FAQ,
  PRE_LOGIN_FOOTER_CTA,
  PRE_LOGIN_HERO,
  PRE_LOGIN_PILLARS,
  PRE_LOGIN_VALUE_PROPOSITION,
  PRICING_TEASER_SECTION,
  PreLoginHighlight,
  PreLoginPillar,
  WHY_MEASUREMENT_MATTERS,
} from '../constants/preLoginDashboardContent';
import { scrollToPageSection } from '../utils/scrollToPageSection';
import { preLoginHorizontalBannerImageSx } from '../constants/bannerIllustrationLayout';
import RouteLoadingGate from './RouteLoadingGate';

const SECTION_ICONS = {
  why: MeasureIcon,
  climate: ClimateIcon,
  benefits: InsightsIcon,
  india: FactoryIcon,
} as const;

const PILLAR_ICONS = [IntelligenceIcon, InsightsIcon, TransitionIcon] as const;

const imageCardSx = {
  borderRadius: 2,
  objectFit: 'cover' as const,
  aspectRatio: '16 / 10',
  bgcolor: 'action.hover',
};

interface SectionBandProps {
  id?: string;
  children: React.ReactNode;
  variant?: 'default' | 'elevated';
  sx?: object;
}

const SectionBand: React.FC<SectionBandProps> = ({ id, children, variant = 'default', sx }) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  return (
    <Box
      id={id}
      component="section"
      sx={{
        py: { xs: 4, md: 5 },
        px: { xs: 0, md: 1 },
        mx: { xs: -0.5, md: 0 },
        borderRadius: { xs: 0, md: 3 },
        bgcolor:
          variant === 'elevated'
            ? isDark
              ? alpha(theme.palette.primary.main, 0.06)
              : alpha(theme.palette.primary.main, 0.03)
            : 'transparent',
        ...sx,
      }}
    >
      {children}
    </Box>
  );
};

interface SectionIntroProps {
  title: string;
  description?: string;
  align?: 'left' | 'center';
}

const SectionIntro: React.FC<SectionIntroProps> = ({ title, description, align = 'left' }) => (
  <Box sx={{ mb: { xs: 2.5, md: 3.5 }, textAlign: align, maxWidth: align === 'center' ? 820 : undefined, mx: align === 'center' ? 'auto' : undefined }}>
    <Typography
      variant="h4"
      component="h2"
      sx={{
        fontWeight: 700,
        letterSpacing: '-0.02em',
        fontSize: { xs: '1.5rem', md: '1.875rem' },
        mb: description ? 1.5 : 0,
      }}
    >
      {title}
    </Typography>
    {description ? (
      <Typography variant="body1" color="text.secondary" sx={{ lineHeight: 1.7, fontSize: { xs: '1rem', md: '1.0625rem' } }}>
        {description}
      </Typography>
    ) : null}
  </Box>
);

interface HighlightSectionProps {
  id: string;
  title: string;
  description?: string;
  items: PreLoginHighlight[];
  icon: React.ElementType;
}

const HighlightSection: React.FC<HighlightSectionProps> = ({ id, title, description, items, icon: SectionIcon }) => {
  const theme = useTheme();

  return (
    <SectionBand id={id}>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: description ? 1 : 2.5 }}>
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: 44,
            height: 44,
            borderRadius: 2,
            bgcolor: alpha(theme.palette.primary.main, 0.1),
            color: 'primary.main',
          }}
        >
          <SectionIcon />
        </Box>
        <Typography variant="h5" component="h2" sx={{ fontWeight: 700, letterSpacing: '-0.01em' }}>
          {title}
        </Typography>
      </Stack>
      {description ? (
        <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 720, lineHeight: 1.7 }}>
          {description}
        </Typography>
      ) : null}
      <Grid container spacing={2.5}>
        {items.map((item) => (
          <Grid item xs={12} sm={6} md={3} key={item.title}>
            <Card
              variant="outlined"
              sx={{
                height: '100%',
                borderColor: alpha(theme.palette.divider, 0.9),
                overflow: 'hidden',
                transition: 'border-color 0.2s, box-shadow 0.2s, transform 0.2s',
                '&:hover': {
                  borderColor: alpha(theme.palette.primary.main, 0.35),
                  boxShadow: theme.shadows[3],
                  transform: 'translateY(-3px)',
                },
              }}
            >
              <CardMedia component="img" image={item.image} alt={item.imageAlt} sx={imageCardSx} />
              <CardContent sx={{ py: 2, px: 2, '&:last-child': { pb: 2 } }}>
                <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.75, letterSpacing: '-0.01em' }}>
                  {item.title}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.65 }}>
                  {item.description}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </SectionBand>
  );
};

interface PillarCardProps {
  pillar: PreLoginPillar;
  icon: React.ElementType;
}

const PillarCard: React.FC<PillarCardProps> = ({ pillar, icon: Icon }) => {
  const theme = useTheme();

  return (
    <Paper
      elevation={0}
      sx={{
        height: '100%',
        p: { xs: 2.5, md: 3 },
        borderRadius: 3,
        border: `1px solid ${alpha(theme.palette.divider, 0.85)}`,
        transition: 'border-color 0.2s, box-shadow 0.2s',
        '&:hover': {
          borderColor: alpha(theme.palette.primary.main, 0.3),
          boxShadow: theme.shadows[2],
        },
      }}
    >
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          width: 48,
          height: 48,
          borderRadius: 2,
          mb: 2,
          bgcolor: alpha(theme.palette.primary.main, 0.1),
          color: 'primary.main',
        }}
      >
        <Icon />
      </Box>
      <Typography variant="h6" component="h3" sx={{ fontWeight: 700, mb: 1, letterSpacing: '-0.01em' }}>
        {pillar.title}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.7 }}>
        {pillar.description}
      </Typography>
    </Paper>
  );
};

const PRE_LOGIN_ABOUT_US_SECTION_ID = 'about-us';

const PreLoginDashboard: React.FC = () => {
  const theme = useTheme();
  const location = useLocation();
  const navigate = useNavigate();
  const { isRegistered, isLoggingOut } = useRegistration();
  const { pricingVisible } = usePublicPricingVisibility();
  const isDark = theme.palette.mode === 'dark';

  useEffect(() => {
    if (isRegistered && !isLoggingOut) {
      navigate('/dashboard', { replace: true });
    }
  }, [isRegistered, isLoggingOut, navigate]);

  useEffect(() => {
    if (location.hash === `#${PRE_LOGIN_ABOUT_US_SECTION_ID}`) {
      scrollToPageSection(PRE_LOGIN_ABOUT_US_SECTION_ID);
    }
  }, [location.hash]);

  if (isLoggingOut) {
    return <RouteLoadingGate message="Signing out…" minHeight="50vh" />;
  }

  if (isRegistered) {
    return null;
  }

  const heroPaperSx = {
    position: 'relative' as const,
    overflow: 'hidden',
    borderRadius: { xs: 2, md: 4 },
    border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.22 : 0.14)}`,
    background: isDark
      ? `linear-gradient(160deg, ${alpha(theme.palette.primary.dark, 0.18)} 0%, ${alpha(theme.palette.background.paper, 0.92)} 55%, ${alpha(theme.palette.background.default, 0.95)} 100%)`
      : `linear-gradient(160deg, ${alpha('#ffffff', 0.98)} 0%, ${alpha(theme.palette.primary.main, 0.04)} 45%, ${alpha(theme.palette.primary.light, 0.08)} 100%)`,
    '&::before': {
      content: '""',
      position: 'absolute',
      top: -120,
      right: -80,
      width: 320,
      height: 320,
      borderRadius: '50%',
      background: alpha(theme.palette.primary.main, isDark ? 0.12 : 0.08),
      pointerEvents: 'none',
    },
  };

  return (
    <Box sx={{ pb: 2 }}>
      <Paper elevation={0} sx={{ ...heroPaperSx, p: { xs: 2.5, sm: 3, md: 4 }, mb: { xs: 3, md: 4 } }}>
        <Box sx={{ textAlign: 'center', mb: { xs: 3, md: 4 }, position: 'relative', zIndex: 1 }}>
          <BrandLockup variant="full" logoSrc={BRAND_BODY_LOGO_SRC} logoWidth="min(480px, 88vw)" />
          <Chip
            icon={<PatentIcon />}
            label={PATENT_PENDING_HIGHLIGHT.label}
            color="primary"
            sx={{
              mt: 2,
              fontWeight: 700,
              px: 0.5,
              border: `1px solid ${alpha(theme.palette.primary.main, 0.4)}`,
              bgcolor: alpha(theme.palette.primary.main, isDark ? 0.16 : 0.08),
              '& .MuiChip-label': { fontSize: '0.875rem' },
            }}
          />
        </Box>

        <Grid container spacing={{ xs: 3, md: 5 }} alignItems="center" sx={{ position: 'relative', zIndex: 1 }}>
          <Grid item xs={12} md={6} sx={{ order: { xs: 2, md: 1 } }}>
            <Chip label={PRE_LOGIN_HERO.chipLabel} size="small" color="primary" variant="outlined" sx={{ mb: 2.5, fontWeight: 600 }} />
            <Typography
              variant="h3"
              component="h1"
              gutterBottom
              sx={{
                fontWeight: 800,
                letterSpacing: '-0.03em',
                fontSize: { xs: '1.875rem', sm: '2.125rem', md: '2.5rem' },
                lineHeight: 1.15,
                color: 'text.primary',
                mb: 2,
              }}
            >
              {PRE_LOGIN_HERO.title}
            </Typography>
            <Typography
              variant="h6"
              color="text.secondary"
              sx={{ mb: 3, fontWeight: 400, lineHeight: 1.65, fontSize: { xs: '1rem', md: '1.125rem' }, maxWidth: 560 }}
            >
              {PRE_LOGIN_HERO.subtitle}
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} flexWrap="wrap" useFlexGap>
              <Button
                component={RouterLink}
                to="/register?type=msme"
                variant="contained"
                size="large"
                startIcon={<RegisterIcon />}
                aria-label={PRE_LOGIN_HERO.registerAriaLabel}
                sx={{
                  py: 1.35,
                  px: 2.5,
                  fontWeight: 700,
                  background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                  '&:hover': {
                    background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                  },
                }}
              >
                Get started
              </Button>
              <Button
                component="a"
                href={`mailto:${PRE_LOGIN_HERO.contactEmail}`}
                variant="outlined"
                size="large"
                startIcon={<ContactIcon />}
                color="primary"
                sx={{ py: 1.35, px: 2.5, fontWeight: 600 }}
              >
                {PRE_LOGIN_HERO.contactLabel}
              </Button>
              <Button
                component={RouterLink}
                to="/login"
                variant="text"
                size="large"
                startIcon={<LoginIcon />}
                aria-label={PRE_LOGIN_HERO.loginAriaLabel}
                color="primary"
                sx={{ py: 1.35, fontWeight: 600 }}
              >
                {PRE_LOGIN_HERO.loginLabel}
              </Button>
              <Button
                variant="text"
                size="large"
                startIcon={<OffsetsIcon />}
                color="primary"
                onClick={() => scrollToPageSection('carbon-offsets')}
                sx={{ py: 1.35, fontWeight: 600 }}
              >
                Carbon offsets
              </Button>
              {pricingVisible ? (
                <Button
                  component={RouterLink}
                  to="/pricing"
                  variant="text"
                  size="large"
                  startIcon={<PricingIcon />}
                  color="primary"
                  sx={{ py: 1.35, fontWeight: 600 }}
                >
                  Pricing
                </Button>
              ) : null}
            </Stack>
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2.5 }}>
              <Chip icon={<EcoIcon />} label="GHG scopes 1–3" size="small" variant="outlined" />
              <Chip icon={<SavingsIcon />} label="Carbon savings" size="small" variant="outlined" />
              <Chip icon={<OffsetsIcon />} label="Carbon offsets" size="small" variant="outlined" />
              <Chip icon={<FinanceIcon />} label="Green finance" size="small" variant="outlined" />
            </Stack>
          </Grid>
          <Grid item xs={12} md={6} sx={{ order: { xs: 1, md: 2 } }}>
            <Box
              component="img"
              src={PRE_LOGIN_HERO.image}
              alt={PRE_LOGIN_HERO.imageAlt}
              sx={{
                ...preLoginHorizontalBannerImageSx,
                borderRadius: 3,
                border: `1px solid ${alpha(theme.palette.divider, 0.5)}`,
                boxShadow: isDark ? theme.shadows[8] : '0 20px 50px rgba(15, 23, 42, 0.12)',
              }}
            />
          </Grid>
        </Grid>
      </Paper>

      <SectionBand variant="elevated" sx={{ px: { xs: 2, md: 3 }, mx: { xs: -1, md: 0 }, borderRadius: { xs: 2, md: 3 } }}>
        <SectionIntro
          title={PRE_LOGIN_VALUE_PROPOSITION.title}
          description={PRE_LOGIN_VALUE_PROPOSITION.description}
          align="center"
        />
        <Grid container spacing={2.5}>
          {PRE_LOGIN_PILLARS.map((pillar, index) => (
            <Grid item xs={12} md={4} key={pillar.title}>
              <PillarCard pillar={pillar} icon={PILLAR_ICONS[index] ?? IntelligenceIcon} />
            </Grid>
          ))}
        </Grid>
      </SectionBand>

      <Divider sx={{ my: { xs: 1, md: 2 }, opacity: 0.6 }} />

      <HighlightSection
        id="why-measure"
        title="Why carbon measurement matters"
        description="Understand emissions alongside cost and operations to meet buyer, lender, and regulatory expectations."
        items={WHY_MEASUREMENT_MATTERS}
        icon={SECTION_ICONS.why}
      />

      <HighlightSection
        id="climate-savings"
        title="Climate impact & carbon savings"
        description="Track scope-wise visibility, quantify avoided emissions, and connect spend lines to carbon hotspots."
        items={CLIMATE_AND_SAVINGS_HIGHLIGHTS}
        icon={SECTION_ICONS.climate}
      />

      <SectionBand id="carbon-offsets" variant="elevated" sx={{ px: { xs: 2, md: 3 }, mx: { xs: -1, md: 0 }, borderRadius: { xs: 2, md: 3 } }}>
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} md={6}>
            <Box
              component="img"
              src={CARBON_OFFSET_TEASER_SECTION.image}
              alt={CARBON_OFFSET_TEASER_SECTION.imageAlt}
              sx={{
                ...preLoginHorizontalBannerImageSx,
                borderRadius: 3,
                border: `1px solid ${alpha(theme.palette.divider, 0.5)}`,
                boxShadow: theme.shadows[3],
              }}
            />
          </Grid>
          <Grid item xs={12} md={6}>
            <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 1.5 }}>
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 44,
                  height: 44,
                  borderRadius: 2,
                  bgcolor: alpha(theme.palette.secondary.main, 0.1),
                  color: 'secondary.main',
                }}
              >
                <OffsetsIcon />
              </Box>
              <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
                {CARBON_OFFSET_TEASER_SECTION.title}
              </Typography>
            </Stack>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 2.5, lineHeight: 1.7 }}>
              {CARBON_OFFSET_TEASER_SECTION.description}
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} flexWrap="wrap" useFlexGap>
              <Button component={RouterLink} to="/register?type=msme" variant="contained" color="secondary" startIcon={<OffsetsIcon />}>
                {CARBON_OFFSET_TEASER_SECTION.ctaMarketplace}
              </Button>
              <Button component={RouterLink} to="/register?type=msme" variant="outlined" startIcon={<RegisterIcon />}>
                {CARBON_OFFSET_TEASER_SECTION.ctaRegister}
              </Button>
              <Button component={RouterLink} to="/login" variant="text" startIcon={<LoginIcon />} color="primary">
                {CARBON_OFFSET_TEASER_SECTION.ctaLogin}
              </Button>
            </Stack>
          </Grid>
        </Grid>
      </SectionBand>

      {pricingVisible ? (
        <SectionBand id="pricing">
          <Grid container spacing={3} alignItems="center">
            <Grid item xs={12} md={6}>
              <Box
                component="img"
                src={PRICING_TEASER_SECTION.image}
                alt={PRICING_TEASER_SECTION.imageAlt}
                sx={{
                  ...preLoginHorizontalBannerImageSx,
                  borderRadius: 3,
                  border: `1px solid ${alpha(theme.palette.divider, 0.5)}`,
                  boxShadow: theme.shadows[3],
                }}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 1.5 }}>
                <Box
                  sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: 44,
                    height: 44,
                    borderRadius: 2,
                    bgcolor: alpha(theme.palette.primary.main, 0.1),
                    color: 'primary.main',
                  }}
                >
                  <PricingIcon />
                </Box>
                <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
                  {PRICING_TEASER_SECTION.title}
                </Typography>
              </Stack>
              <Typography variant="body1" color="text.secondary" sx={{ mb: 2.5, lineHeight: 1.7 }}>
                {PRICING_TEASER_SECTION.description}
              </Typography>
              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} flexWrap="wrap" useFlexGap>
                <Button
                  component={RouterLink}
                  to="/pricing"
                  variant="contained"
                  startIcon={<PricingIcon />}
                  sx={{
                    background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                    '&:hover': {
                      background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                    },
                  }}
                >
                  {PRICING_TEASER_SECTION.ctaPricing}
                </Button>
                <Button component={RouterLink} to="/register?type=msme" variant="outlined" startIcon={<RegisterIcon />}>
                  {PRICING_TEASER_SECTION.ctaRegister}
                </Button>
                <Button component={RouterLink} to="/login" variant="text" startIcon={<LoginIcon />} color="primary">
                  {PRICING_TEASER_SECTION.ctaLogin}
                </Button>
              </Stack>
            </Grid>
          </Grid>
        </SectionBand>
      ) : null}

      <HighlightSection
        id="benefits"
        title="Platform benefits after sign-in"
        description="From document capture to compliance reporting—everything you need in one MSME-sized workspace."
        items={PLATFORM_BENEFITS}
        icon={SECTION_ICONS.benefits}
      />

      <HighlightSection
        id="india"
        title="India-specific context"
        description="Built for domestic supply chains, BRSR value-chain expectations, and emerging carbon-market programmes."
        items={INDIA_SPECIFIC_INFO}
        icon={SECTION_ICONS.india}
      />

      <SectionBand id="about-us">
        <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2.5 }}>
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: 44,
              height: 44,
              borderRadius: 2,
              bgcolor: alpha(theme.palette.primary.main, 0.1),
              color: 'primary.main',
            }}
          >
            <AboutIcon />
          </Box>
          <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
            {ABOUT_US_SECTION.title}
          </Typography>
        </Stack>
        <Paper
          elevation={0}
          sx={{
            p: { xs: 2.5, md: 3.5 },
            borderRadius: 3,
            border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.35 : 0.22)}`,
            bgcolor: alpha(theme.palette.primary.main, isDark ? 0.08 : 0.04),
          }}
        >
          <Stack direction="row" spacing={1.5} alignItems="flex-start" sx={{ mb: 2 }}>
            <PatentIcon color="primary" sx={{ mt: 0.25 }} />
            <Box>
              <Typography variant="subtitle1" sx={{ fontWeight: 800, color: 'primary.main', mb: 0.5 }}>
                {PATENT_PENDING_HIGHLIGHT.label}
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.65 }}>
                {PATENT_PENDING_HIGHLIGHT.description}
              </Typography>
            </Box>
          </Stack>
          <Typography variant="body1" sx={{ fontWeight: 600, mb: 1.5, lineHeight: 1.65 }}>
            {ABOUT_US_SECTION.lead}
          </Typography>
          {ABOUT_US_SECTION.paragraphs.map((paragraph) => (
            <Typography key={paragraph.slice(0, 48)} variant="body2" color="text.secondary" sx={{ mb: 1.5, lineHeight: 1.65 }}>
              {paragraph}
            </Typography>
          ))}
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2, lineHeight: 1.65 }}>
            Questions or partnerships? See our <RouterLink to="/partners">Partners page</RouterLink> or reach us at{' '}
            <Box
              component="a"
              href={`mailto:${ABOUT_US_SECTION.contactEmail}`}
              sx={{ color: 'primary.main', fontWeight: 600, textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
            >
              {ABOUT_US_SECTION.contactEmail}
            </Box>
            .
          </Typography>
          <Button component={RouterLink} to="/about-us" variant="outlined" endIcon={<ArrowForwardIcon />}>
            Read full About us
          </Button>
        </Paper>
      </SectionBand>

      <SectionBand id="workflow">
        <SectionIntro title="Your workflow after login" description="Four steps from registration to continuous improvement." />
        <Grid container spacing={2.5}>
          {POST_LOGIN_WORKFLOW.map((step) => (
            <Grid item xs={12} sm={6} md={3} key={step.step}>
              <Paper
                elevation={0}
                sx={{
                  height: '100%',
                  overflow: 'hidden',
                  borderRadius: 3,
                  border: `1px solid ${alpha(theme.palette.divider, 0.85)}`,
                  transition: 'box-shadow 0.2s, transform 0.2s',
                  '&:hover': {
                    boxShadow: theme.shadows[3],
                    transform: 'translateY(-2px)',
                  },
                }}
              >
                <Box sx={{ position: 'relative' }}>
                  <Box
                    component="img"
                    src={step.image}
                    alt={step.imageAlt}
                    sx={{ width: '100%', display: 'block', ...imageCardSx, borderRadius: 0 }}
                  />
                  <Chip
                    label={`Step ${step.step}`}
                    size="small"
                    color="primary"
                    sx={{
                      position: 'absolute',
                      top: 12,
                      left: 12,
                      fontWeight: 700,
                    }}
                  />
                </Box>
                <Box sx={{ p: 2 }}>
                  <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
                    {step.title}
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.65 }}>
                    {step.description}
                  </Typography>
                </Box>
              </Paper>
            </Grid>
          ))}
        </Grid>
      </SectionBand>

      <SectionBand id="faq" variant="elevated" sx={{ px: { xs: 2, md: 3 }, mx: { xs: -1, md: 0 }, borderRadius: { xs: 2, md: 3 } }}>
        <SectionIntro title="Frequently asked questions" align="center" />
        <Box sx={{ maxWidth: 860, mx: 'auto' }}>
          {PRE_LOGIN_FAQ.map((item) => (
            <Accordion
              key={item.question}
              disableGutters
              elevation={0}
              sx={{
                mb: 1,
                borderRadius: '12px !important',
                border: `1px solid ${alpha(theme.palette.divider, 0.85)}`,
                '&::before': { display: 'none' },
                bgcolor: 'background.paper',
              }}
            >
              <AccordionSummary expandIcon={<ExpandMoreIcon />} sx={{ px: 2.5, py: 0.5 }}>
                <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                  {item.question}
                </Typography>
              </AccordionSummary>
              <AccordionDetails sx={{ px: 2.5, pt: 0, pb: 2 }}>
                <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.7 }}>
                  {item.answer}
                </Typography>
              </AccordionDetails>
            </Accordion>
          ))}
        </Box>
      </SectionBand>

      <Paper
        elevation={0}
        sx={{
          mt: { xs: 3, md: 4 },
          p: { xs: 2.5, md: 4 },
          borderRadius: 4,
          overflow: 'hidden',
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.24 : 0.16)}`,
          bgcolor: alpha(theme.palette.primary.main, isDark ? 0.08 : 0.04),
        }}
      >
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} md={5}>
            <Box
              component="img"
              src={PRE_LOGIN_HERO.image}
              alt="Preview of emissions dashboard after sign-in"
              sx={{
                ...preLoginHorizontalBannerImageSx,
                borderRadius: 3,
                border: `1px solid ${alpha(theme.palette.divider, 0.5)}`,
              }}
            />
          </Grid>
          <Grid item xs={12} md={7} sx={{ textAlign: { xs: 'center', md: 'left' } }}>
            <Typography variant="h5" sx={{ fontWeight: 700, mb: 1, letterSpacing: '-0.02em' }}>
              {PRE_LOGIN_FOOTER_CTA.title}
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 2.5, lineHeight: 1.65 }}>
              Start measuring at your scale with a workspace built for Indian MSME operating realities.
            </Typography>
            <Stack
              direction={{ xs: 'column', sm: 'row' }}
              spacing={1.5}
              justifyContent={{ xs: 'center', md: 'flex-start' }}
              flexWrap="wrap"
              useFlexGap
            >
              <Button
                component={RouterLink}
                to="/register?type=msme"
                variant="contained"
                size="large"
                endIcon={<ArrowForwardIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                  '&:hover': {
                    background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                  },
                }}
              >
                {PRE_LOGIN_FOOTER_CTA.registerLabel}
              </Button>
              <Button component={RouterLink} to="/login" variant="outlined" size="large" startIcon={<LoginIcon />} color="primary">
                {PRE_LOGIN_FOOTER_CTA.loginLabel}
              </Button>
              <Button
                component="a"
                href={`mailto:${PRE_LOGIN_HERO.contactEmail}`}
                variant="text"
                size="large"
                startIcon={<ContactIcon />}
                color="primary"
              >
                {PRE_LOGIN_HERO.contactLabel}
              </Button>
            </Stack>
          </Grid>
        </Grid>
      </Paper>
    </Box>
  );
};

export default PreLoginDashboard;
