/**
 * Parse REACT_APP_* booleans: "true" / "1" → true; "false" / "0" → false; unset → default.
 */
const envFlag = (key: string, defaultValue: boolean): boolean => {
  const raw = process.env[key];
  if (raw === undefined || raw === '') {
    return defaultValue;
  }
  const normalized = String(raw).trim().toLowerCase();
  if (normalized === 'true' || normalized === '1') {
    return true;
  }
  if (normalized === 'false' || normalized === '0') {
    return false;
  }
  return defaultValue;
};

/**
 * When true, ISO 14067 reporting surfaces and related copy are hidden in the web app.
 * Default: visible (false).
 */
export const HIDE_ISO_14067_UI = envFlag('REACT_APP_HIDE_ISO_14067_UI', false);

/**
 * When true, the Documents page omits transaction mapping / product attribution
 * controls and does not display extracted or user-mapped company–product detail.
 * Default: hidden (true) unless REACT_APP_HIDE_DOCUMENTS_SENSITIVE_INPUTS_UI=false.
 */
export const HIDE_DOCUMENTS_SENSITIVE_INPUTS_UI = envFlag(
  'REACT_APP_HIDE_DOCUMENTS_SENSITIVE_INPUTS_UI',
  true
);

/**
 * Email ingestion (UC3) is permanently hidden in the web UI.
 * Backend email APIs remain available for administrative use only.
 */
export const EMAIL_DATA_SOURCE_UI_ENABLED = false;
