import React, { useEffect, useState } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Paper,
  ToggleButton,
  ToggleButtonGroup,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip as RechartsTooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  cartesianGridStroke,
  chartAnimationProps,
  rechartsTooltipProps,
} from '../../theme/rechartsAppearances';
import {
  CO2E_METHODOLOGY_SUBTITLE,
  GHG_SCOPE_COLORS,
  rechartsTonnesAxisLabelProps,
  rechartsTonnesTooltipFormatter,
} from '../../constants/carbonVisualization';
import { EmissionsChartDataTable } from './EmissionsChartDataTable';

const CATEGORY_BAR_PALETTE = [
  '#00695c',
  '#00897b',
  '#26a69a',
  '#4db6ac',
  '#ff8f00',
  '#fb8c00',
  '#6d4c41',
  '#5e35b1',
];

export interface EmissionSourceRow {
  name: string;
  kg: number;
  tCO2e: number;
}

export interface ScopeSplitRow {
  name: string;
  kg: number;
  tCO2e: number;
  fill: string;
}

interface DashboardEmissionsChartsProps {
  emissionSourceBarData: EmissionSourceRow[];
  scopeSplitBarData: ScopeSplitRow[];
  mutedInsetSurfaceSx: Record<string, unknown>;
}

type ChartView = 'source' | 'scope';

export const DashboardEmissionsCharts: React.FC<DashboardEmissionsChartsProps> = ({
  emissionSourceBarData,
  scopeSplitBarData,
  mutedInsetSurfaceSx,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const chartGridStroke = cartesianGridStroke(isDark);
  const chartTooltipProps = rechartsTooltipProps(isDark);

  const hasSource = emissionSourceBarData.length > 0;
  const hasScope = scopeSplitBarData.length > 0;
  const hasAny = hasSource || hasScope;

  const defaultView: ChartView = hasSource ? 'source' : 'scope';
  const [chartView, setChartView] = useState<ChartView>(defaultView);
  const [showDataTable, setShowDataTable] = useState(false);

  useEffect(() => {
    if (chartView === 'source' && !hasSource && hasScope) setChartView('scope');
    if (chartView === 'scope' && !hasScope && hasSource) setChartView('source');
  }, [chartView, hasSource, hasScope]);

  useEffect(() => {
    setShowDataTable(false);
  }, [chartView]);

  const handleViewChange = (_: React.MouseEvent<HTMLElement>, next: ChartView | null) => {
    if (next) setChartView(next);
  };

  return (
    <Card sx={{ border: `1px solid ${alpha(theme.palette.primary.dark, isDark ? 0.4 : 0.22)}` }}>
      <CardContent>
        <Box
          sx={{
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            alignItems: { xs: 'flex-start', sm: 'center' },
            justifyContent: 'space-between',
            gap: 1.5,
            mb: 2,
          }}
        >
          <Box>
            <Typography variant="h6" sx={{ fontWeight: 700 }}>
              Emissions breakdown
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 720, mt: 0.5 }}>
              Activity drivers and GHG Protocol scope split from your latest assessment (tCO₂e).
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.75 }}>
              {CO2E_METHODOLOGY_SUBTITLE}
            </Typography>
          </Box>
          {hasSource && hasScope ? (
            <ToggleButtonGroup
              exclusive
              size="small"
              value={chartView}
              onChange={handleViewChange}
              aria-label="Emissions chart view"
            >
              <ToggleButton value="source">By source</ToggleButton>
              <ToggleButton value="scope">By scope</ToggleButton>
            </ToggleButtonGroup>
          ) : null}
        </Box>

        {!hasAny ? (
          <Paper variant="outlined" sx={{ p: 3, textAlign: 'center', ...mutedInsetSurfaceSx }}>
            <Typography variant="body2" color="text.secondary">
              Complete a carbon assessment so category lines or scope breakdowns can populate these charts.
            </Typography>
          </Paper>
        ) : chartView === 'source' && hasSource ? (
          <>
            <Box
              sx={{ width: '100%', height: 340 }}
              role="img"
              aria-label="Bar chart of emissions by activity source"
              aria-describedby="emissions-source-data-table"
            >
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  layout="vertical"
                  data={emissionSourceBarData}
                  margin={{ left: 8, right: 16, top: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke={chartGridStroke} vertical={false} />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}`}
                    label={rechartsTonnesAxisLabelProps({ fill: isDark ? '#94a3b8' : '#64748b' })}
                  />
                  <YAxis type="category" dataKey="name" width={130} tick={{ fontSize: 11 }} interval={0} />
                  <RechartsTooltip {...chartTooltipProps} formatter={rechartsTonnesTooltipFormatter} />
                  <Bar dataKey="tCO2e" name="tCO₂e" radius={[0, 6, 6, 0]} {...chartAnimationProps}>
                    {emissionSourceBarData.map((entry, index) => (
                      <Cell
                        key={`src-${entry.name}`}
                        fill={CATEGORY_BAR_PALETTE[index % CATEGORY_BAR_PALETTE.length]}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </Box>
            <EmissionsChartDataTable
              chartView="source"
              emissionSourceBarData={emissionSourceBarData}
              scopeSplitBarData={scopeSplitBarData}
              showDataTable={showDataTable}
              onToggleDataTable={() => setShowDataTable((prev) => !prev)}
            />
          </>
        ) : hasScope ? (
          <>
            <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, alignItems: 'center', gap: 3 }}>
              <Box
                sx={{ width: '100%', maxWidth: 360, height: 280, position: 'relative' }}
                role="img"
                aria-label="Donut chart of scope 1 2 and 3 emissions"
                aria-describedby="emissions-scope-data-table"
              >
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={scopeSplitBarData}
                    dataKey="tCO2e"
                    nameKey="name"
                    innerRadius={62}
                    outerRadius={100}
                    paddingAngle={2}
                    {...chartAnimationProps}
                  >
                    {scopeSplitBarData.map((entry) => (
                      <Cell key={entry.name} fill={entry.fill} />
                    ))}
                  </Pie>
                  <RechartsTooltip {...chartTooltipProps} formatter={rechartsTonnesTooltipFormatter} />
                </PieChart>
              </ResponsiveContainer>
            </Box>
            <Box sx={{ flex: 1, width: '100%' }}>
              {scopeSplitBarData.map((row) => (
                <Box
                  key={row.name}
                  sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    py: 1,
                    borderBottom: `1px solid ${alpha(theme.palette.divider, 0.6)}`,
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Box sx={{ width: 10, height: 10, borderRadius: '50%', bgcolor: row.fill }} />
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>
                      {row.name}
                    </Typography>
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    {row.tCO2e.toFixed(2)} tCO₂e
                  </Typography>
                </Box>
              ))}
              <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1.5 }}>
                {GHG_SCOPE_COLORS.scope1.label}: direct · {GHG_SCOPE_COLORS.scope2.label}: purchased energy ·{' '}
                {GHG_SCOPE_COLORS.scope3.label}: value chain
              </Typography>
            </Box>
          </Box>
            <EmissionsChartDataTable
              chartView="scope"
              emissionSourceBarData={emissionSourceBarData}
              scopeSplitBarData={scopeSplitBarData}
              showDataTable={showDataTable}
              onToggleDataTable={() => setShowDataTable((prev) => !prev)}
            />
          </>
        ) : (
          <Paper variant="outlined" sx={{ p: 3, textAlign: 'center', ...mutedInsetSurfaceSx }}>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              No chart data for this view yet. Upload transactions or run a carbon assessment to populate scope breakdowns.
            </Typography>
            <Button component={RouterLink} to="/carbon-footprint?section=start-assessment" size="small" variant="outlined">
              Start assessment
            </Button>
          </Paper>
        )}
      </CardContent>
    </Card>
  );
};
